import React, { Component } from 'react';
import MyContext from '../contexts/MyContext';

class Menu extends Component {
  static contextType = MyContext;

  lnkLogoutClick() {
    this.context.setToken('');
    this.context.setUsername('');
  }

  render() {
    return (
      <div style={{ padding: '10px 0', borderBottom: '1px solid #ccc', marginBottom: '20px' }}>
        <div style={{ float: 'left' }}>
          <ul style={{ listStyleType: 'none', margin: 0, padding: 0 }}>
            <li style={{ display: 'inline', marginRight: '20px' }}><a href="#home">Home</a></li>
            <li style={{ display: 'inline', marginRight: '20px' }}><a href="#category">Category</a></li>
            <li style={{ display: 'inline', marginRight: '20px' }}><a href="#product">Product</a></li>
            <li style={{ display: 'inline', marginRight: '20px' }}><a href="#order">Order</a></li>
          </ul>
        </div>
        <div style={{ float: 'right' }}>
          Hello <b>{this.context.username}</b> | {' '}
          <a href="#logout" onClick={() => this.lnkLogoutClick()}>Logout</a>
        </div>
        <div style={{ clear: 'both' }} />
      </div>
    );
  }
}

export default Menu;
